{"content": "生成猫咪表情包宫格图", "next": [{"mcp": "generate_grid_image", "args": {"theme": "可爱猫咪表情包，各种有趣的猫咪表情和姿势", "rows": 4, "cols": 4, "layoutStyle": "grid"}}]}

